		parentId: null,
		timestamp: DEFAULT_TIMESTAMP,
		customType: OM_OBSERVATIONS_DROPPED,
		data: args,
		...overrides,
	};
}

export function unknownCustomEntry(id: string, customType: string, data: unknown = {}): TestEntry {
	return {
		type: "custom",
		id,
		parentId: null,
		timestamp: DEFAULT_TIMESTAMP,
		customType,
		data,
	};
}

